//! `AET-WO-3401` §1.3, tier 1: Sentinel-01 as ordered ("V0+",
//! `examples/sentinel-01.json`) has a board directory of its own,
//! `boards/sentinel-01-bench/`, so the reference (`sentinel-01-minimal.json`,
//! `boards/sentinel-01/`) stays P1's byte-for-byte fixture. The directory is
//! regenerated by `aethelgard-svd-hal/tests/board.rs`, as the reference's is.
//! Here: the specification validates, so its acknowledgements name exactly
//! the ledger's rows, the EXT bus's I2C2 rows included (`generate` does not
//! check them; `validate` and `verify` do).
//!
//! The committed fabrication package (`fab/sentinel-01-bench/package/`) is
//! bound here to its inputs, per pull request, in seconds (ruling Q1 (i) on
//! PR #190): this specification's and topology's hashes, the scenarios'
//! names and hashes in order, every file against `MANIFEST.json`, and
//! `emit`'s bill of materials byte for byte. The package itself is derived
//! again by `verify --against-fab` in `ci.yml`'s `bench-package` job, on
//! `main`'s push and on `workflow_dispatch`: one verify, too slow per PR.

use std::collections::BTreeMap;
use std::fs;
use std::path::{Path, PathBuf};
use std::process::{Command, Stdio};

use serde_json::{Value, json};
use sha2::{Digest, Sha256};

const SPEC: &str = "examples/sentinel-01.json";
const PACKAGE: &str = "fab/sentinel-01-bench/package";
/// The scenarios the package was verified with, in the order `MANIFEST.json`
/// records and `ci.yml`'s `bench-package` job passes them.
const SCENARIOS: [&str; 6] = [
    "scenarios/sentinel-01-bench/pullup-3k3.json",
    "scenarios/sentinel-01-bench/droop-bor3.json",
    "scenarios/sentinel-01-bench/spi-absent-u4.json",
    "scenarios/sentinel-01-bench/pullup-2k2.json",
    "scenarios/sentinel-01-bench/serial-rx-open-console.json",
    // `AET-WO-4310` (5), ruled D7 (i): SENSORS covered by a detected fault.
    "scenarios/sentinel-01-bench/held-low-sda.json",
];

fn root() -> PathBuf {
    fs::canonicalize(Path::new(env!("CARGO_MANIFEST_DIR")).join("../..")).unwrap()
}

/// Runs the binary from the repository root with an empty `PATH`: neither
/// `validate`, `solve` nor `emit` starts a tool.
fn run(args: &[&str]) -> (Option<i32>, Value) {
    let (code, stdout) = run_raw(args);
    (code, serde_json::from_str(&stdout).unwrap())
}

/// [`run`], with stdout as printed: one line.
fn run_raw(args: &[&str]) -> (Option<i32>, String) {
    let out = Command::new(env!("CARGO_BIN_EXE_aethelgard"))
        .args(args)
        .current_dir(root())
        .stdin(Stdio::null())
        .env("PATH", "")
        .output()
        .unwrap();
    let stdout = String::from_utf8(out.stdout).unwrap();
    assert_eq!(stdout.lines().count(), 1, "{args:?}: {stdout}");
    (out.status.code(), stdout)
}

/// The committed package's `MANIFEST.json`.
fn manifest() -> Value {
    serde_json::from_slice(&fs::read(root().join(PACKAGE).join("MANIFEST.json")).unwrap()).unwrap()
}

fn sha(bytes: &[u8]) -> String {
    Sha256::digest(bytes)
        .iter()
        .map(|b| format!("{b:02x}"))
        .collect()
}

#[test]
fn the_ordered_board_validates() {
    let (code, v) = run(&["validate", "--file", SPEC]);
    assert_eq!(code, Some(0), "{v}");
    assert_eq!(v["project_name"], "sentinel-01-bench", "{v}");
}

/// Ruling Q1 (i) on PR #190, the per-PR half: the committed package names
/// this specification, its solved topology and its scenarios by hash, holds
/// exactly the files its manifest names with those hashes, and carries the
/// bill of materials `emit` writes today, byte for byte.
#[test]
fn the_committed_package_is_bound_to_its_specification_scenarios_and_emit() {
    let pkg = root().join(PACKAGE);
    let manifest = manifest();
    assert_eq!(manifest["project"], "sentinel-01-bench");
    assert_eq!(
        manifest["specification_sha256"],
        sha(&fs::read(root().join(SPEC)).unwrap()),
        "the package was made from another specification: run verify --fab-out again"
    );
    let (code, line) = run_raw(&["solve", "--file", SPEC]);
    assert_eq!(code, Some(0), "{line}");
    assert_eq!(manifest["topology_sha256"], sha(line.trim_end().as_bytes()));

    let scenarios: Vec<Value> = SCENARIOS
        .iter()
        .map(|p| {
            let bytes = fs::read(root().join(p)).unwrap();
            let v: Value = serde_json::from_slice(&bytes).unwrap();
            json!({ "scenario": v["name"], "sha256": sha(&bytes) })
        })
        .collect();
    assert_eq!(manifest["scenarios"], Value::Array(scenarios));

    let mut on_disk = BTreeMap::new();
    for entry in fs::read_dir(&pkg).unwrap() {
        let path = entry.unwrap().path();
        let name = path.file_name().unwrap().to_str().unwrap().to_owned();
        assert!(path.is_file(), "{name} is not a regular file");
        if name != "MANIFEST.json" {
            on_disk.insert(name, Value::String(sha(&fs::read(&path).unwrap())));
        }
    }
    let named: BTreeMap<String, Value> = manifest["files"]
        .as_object()
        .unwrap()
        .iter()
        .map(|(k, v)| (k.clone(), v.clone()))
        .collect();
    assert_eq!(
        named, on_disk,
        "the package's files and its manifest disagree"
    );

    let out = Path::new(env!("CARGO_TARGET_TMPDIR"))
        .join(format!("aet-3401-package-{}", std::process::id()));
    let _ = fs::remove_dir_all(&out);
    let (code, v) = run(&["emit", "--file", SPEC, "--out", out.to_str().unwrap()]);
    assert_eq!(code, Some(0), "{v}");
    assert!(
        fs::read(out.join("sentinel-01-bench.bom.csv")).unwrap()
            == fs::read(pkg.join("sentinel-01-bench.bom.csv")).unwrap(),
        "emit's bill of materials is not the package's"
    );
    fs::remove_dir_all(&out).unwrap();
}

// ---- AET-WO-3308: what was ordered, and the bench sheet's ELF -------------------------------------------------

/// The fabrication files as ordered, by hash (`AET-WO-3308` (1)): the ten
/// files `ORDER.md` §1 uploads. A re-spin edits it only by a ruling.
const ORDERED: &str = "fab/sentinel-01-bench/ORDERED.sha256";
/// The bench sheet, which names the ELF it predicts (`AET-WO-3308` (3)).
const BENCH: &str = "fab/sentinel-01-bench/BENCH.md";
/// Every file of `package/` that was not uploaded to the fabricator. With the
/// list's ten, the package's whole name set, closed (ruling D2 on PR #362): a
/// file under any other name, whatever its extension, is a finding.
const NOT_ORDERED: [&str; 7] = [
    "FAB-NOTES.md",
    "MANIFEST.json",
    "sentinel-01-bench-jlcpcb-bom.csv",
    "sentinel-01-bench-jlcpcb-cpl.csv",
    "sentinel-01-bench-pos.csv",
    "sentinel-01-bench.bom.csv",
    "sentinel-01-bench.elf",
];
/// The digests `BENCH.md` may cite that are not an ELF's, by their first
/// eight hex digits (ruling D3 on PR #362), each with what it is.
const NOT_AN_ELF: [(&str, &str); 2] = [
    (
        "78212e91",
        "TI SNOSD82D, the TMP117 datasheet (AET-WO-4241 FEEDBACK §8)",
    ),
    ("452d906c", "the W25Q64JV row of parts.json"),
];
/// [`NOT_AN_ELF`] for Sentinel-03's sheet (`fab/sentinel-03/BENCH.md`).
const S03_NOT_AN_ELF: [(&str, &str); 1] = [(
    "1206F700",
    "no digest: Bourns SF-1206F700-2, F1's part number, in B-1's source line (AET-WO-4411)",
)];

/// The sha256 of `ORDERED.sha256`'s as-ordered block: its header and the ten
/// entries, every byte before the first ruling block. Its header says nothing
/// in it is rewritten; a re-spin adds a dated ruling block below it.
const AS_ORDERED_SHA256: &str = "a71977376474c757244894722c56d246e095821df4c3102c021d7192c7a248f1";

/// Whether `line` opens a ruling block: `# Ruling YYYY-MM-DD`.
fn opens_ruling(line: &str) -> bool {
    line.strip_prefix("# Ruling ").is_some_and(|rest| {
        let d = rest.as_bytes();
        d.len() >= 10
            && d[..10].iter().enumerate().all(|(i, c)| {
                if i == 4 || i == 7 {
                    *c == b'-'
                } else {
                    c.is_ascii_digit()
                }
            })
    })
}

/// One entry, `<64 lowercase hex>  package/<name>`, as (hash, name).
fn ordered_entry(line: &str) -> Option<(String, String)> {
    let (hash, path) = line.split_once("  ")?;
    let name = path.strip_prefix("package/")?;
    let hash_ok = hash.len() == 64
        && hash
            .bytes()
            .all(|b| b.is_ascii_digit() || (b'a'..=b'f').contains(&b));
    let name_ok = !name.is_empty()
        && name
            .bytes()
            .all(|b| b.is_ascii_alphanumeric() || b"._-".contains(&b));
    (hash_ok && name_ok).then(|| (hash.to_owned(), name.to_owned()))
}

/// Parses `ORDERED.sha256`: the as-ordered block (`#` header lines, then
/// entries), then any ruling blocks, each opening `# Ruling YYYY-MM-DD` and
/// holding entries that supersede the same name above. Returns the
/// as-ordered block's text and the list in force. Refuses CRLF, a missing
/// final newline, an empty or malformed line, a block below the header that does not open with a dated
/// ruling, and a name listed twice in one block.
fn parse_ordered(text: &str) -> Result<(String, Vec<(String, String)>), String> {
    if text.contains('\r') {
        return Err("a carriage return: the list is LF only".to_owned());
    }
    let Some(body) = text.strip_suffix('\n') else {
        return Err("no final newline".to_owned());
    };
    let (mut list, mut block): (Vec<(String, String)>, Vec<String>) = (Vec::new(), Vec::new());
    let (mut after_entry, mut as_ordered_end, mut offset) = (false, None, 0);
    for (i, line) in body.split('\n').enumerate() {
        if line.starts_with('#') {
            if after_entry {
                if !opens_ruling(line) {
                    return Err(format!(
                        "line {}: a block below the header opens with `# Ruling YYYY-MM-DD`: {line:?}",
                        i + 1
                    ));
                }
                as_ordered_end.get_or_insert(offset);
                block.clear();
                after_entry = false;
            }
        } else {
            let Some(entry) = ordered_entry(line) else {
                return Err(format!("line {}: malformed: {line:?}", i + 1));
            };
            if block.contains(&entry.1) {
                return Err(format!(
                    "line {}: {} is listed twice in one block",
                    i + 1,
                    entry.1
                ));
            }
            block.push(entry.1.clone());
            match list.iter_mut().find(|(_, n)| *n == entry.1) {
                Some(e) => *e = entry,
                None => list.push(entry),
            }
            after_entry = true;
        }
        offset += line.len() + 1;
    }
    let end = as_ordered_end.unwrap_or(text.len());
    Ok((text[..end].to_owned(), list))
}

/// The list in force, once the as-ordered block is the one committed.
fn ordered_in_force(text: &str) -> Result<Vec<(String, String)>, String> {
    let (as_ordered, list) = parse_ordered(text)?;
    if sha(as_ordered.as_bytes()) != AS_ORDERED_SHA256 {
        return Err(format!(
            "the as-ordered block of {ORDERED} was rewritten: a re-spin adds a dated `# Ruling` block below it, and nothing above it changes"
        ));
    }
    Ok(list)
}

/// Every way `pkg` differs from the list: a listed file whose bytes moved or
/// that is gone, and a file outside the list and [`NOT_ORDERED`]. Each names
/// the file.
fn ordered_differences(pkg: &Path, list: &[(String, String)]) -> Vec<String> {
    let mut out = Vec::new();
    for (hash, name) in list {
        match fs::read(pkg.join(name)) {
            Ok(bytes) if sha(&bytes) == *hash => {}
            Ok(_) => out.push(format!("{name}: its bytes are not the ones ordered")),
            Err(_) => out.push(format!("{name}: ordered, and not in the package")),
        }
    }
    for entry in fs::read_dir(pkg).unwrap() {
        let name = entry.unwrap().file_name().into_string().unwrap();
        if !list.iter().any(|(_, n)| *n == name) && !NOT_ORDERED.contains(&name.as_str()) {
            out.push(format!(
                "{name}: in the package, neither ordered nor named as not ordered"
            ));
        }
    }
    out
}

fn ordered_list() -> Vec<(String, String)> {
    ordered_in_force(&fs::read_to_string(root().join(ORDERED)).unwrap()).unwrap()
}

/// `AET-WO-3308` (2): the package holds the ordered bytes, and no other file
/// than those and the named rest.
#[test]
fn the_package_holds_the_files_as_ordered() {
    let list = ordered_list();
    let differences = ordered_differences(&root().join(PACKAGE), &list);
    assert!(
        differences.is_empty(),
        "the package is not what was ordered (a re-spin edits {ORDERED} only by a ruling): {differences:#?}"
    );
}

/// A copy of the package in a scratch directory, for the cases below.
fn package_copy(tag: &str) -> PathBuf {
    let out = Path::new(env!("CARGO_TARGET_TMPDIR"))
        .join(format!("aet-3308-{tag}-{}", std::process::id()));
    let _ = fs::remove_dir_all(&out);
    fs::create_dir_all(&out).unwrap();
    for entry in fs::read_dir(root().join(PACKAGE)).unwrap() {
        let path = entry.unwrap().path();
        fs::copy(&path, out.join(path.file_name().unwrap())).unwrap();
    }
    out
}

/// A package change: what it is, how to make it, and the findings it must give.
type Case = (&'static str, fn(&Path), &'static [&'static str]);

/// Each way a package can stop being what was ordered fails, naming the file.
#[test]
fn a_moved_added_removed_or_split_fabrication_file_is_named() {
    let list = ordered_list();
    let cases: [Case; 5] = [
        (
            "one byte",
            |p| {
                let f = p.join("sentinel-01-bench-B_Mask.gbs");
                let mut b = fs::read(&f).unwrap();
                let last = b.len() - 2;
                b[last] ^= 1;
                fs::write(f, b).unwrap();
            },
            &["sentinel-01-bench-B_Mask.gbs: its bytes"],
        ),
        (
            "a new layer",
            |p| fs::write(p.join("sentinel-01-bench-In1_Cu.gbr"), "G04*\n").unwrap(),
            &["sentinel-01-bench-In1_Cu.gbr: in the package"],
        ),
        (
            "a layer renamed",
            |p| {
                fs::rename(
                    p.join("sentinel-01-bench-Edge_Cuts.gm1"),
                    p.join("sentinel-01-bench-Edge_Cuts.gko"),
                )
                .unwrap();
            },
            &[
                "sentinel-01-bench-Edge_Cuts.gm1: ordered, and not",
                "sentinel-01-bench-Edge_Cuts.gko: in the package",
            ],
        ),
        (
            "the drill split in two",
            |p| {
                let drl = p.join("sentinel-01-bench.drl");
                fs::copy(&drl, p.join("sentinel-01-bench-PTH.drl")).unwrap();
                fs::rename(&drl, p.join("sentinel-01-bench-NPTH.drl")).unwrap();
            },
            &[
                "sentinel-01-bench.drl: ordered, and not",
                "sentinel-01-bench-PTH.drl: in the package",
                "sentinel-01-bench-NPTH.drl: in the package",
            ],
        ),
        (
            "a file removed",
            |p| fs::remove_file(p.join("sentinel-01-bench-F_Paste.gtp")).unwrap(),
            &["sentinel-01-bench-F_Paste.gtp: ordered, and not"],
        ),
    ];
    for (i, (case, change, want)) in cases.iter().enumerate() {
        let pkg = package_copy(&format!("case{i}"));
        assert!(
            ordered_differences(&pkg, &list).is_empty(),
            "{case}: the copy"
        );
        change(&pkg);
        let got = ordered_differences(&pkg, &list);
        assert_eq!(got.len(), want.len(), "{case}: {got:#?}");
        for w in *want {
            assert!(
                got.iter().any(|g| g.starts_with(w)),
                "{case}: {w} not in {got:#?}"
            );
        }
        fs::remove_dir_all(&pkg).unwrap();
    }
}

/// The list's own form: each refusal, the ruling block it accepts, and the
/// as-ordered block held to its committed bytes.
#[test]
fn the_ordered_list_refuses_crlf_a_duplicate_a_malformed_line_and_a_rewrite() {
    let text = fs::read_to_string(root().join(ORDERED)).unwrap();
    let first = text
        .lines()
        .find(|l| !l.starts_with('#'))
        .unwrap()
        .to_owned();
    let (hash, path) = first.split_once("  ").unwrap();
    let refused = |t: String, why: &str| {
        let e = ordered_in_force(&t).expect_err(why);
        assert!(e.contains(why), "{why}: {e}");
    };
    refused(text.replace('\n', "\r\n"), "carriage return");
    refused(text.trim_end().to_owned(), "no final newline");
    refused(format!("{text}{first}\n"), "listed twice in one block");
    for bad in [
        first.replacen("  ", " ", 1),
        first.replacen("  ", "  ./", 1),
        first.replacen("package/", "", 1),
        format!("{first} "),
        format!("{}  {path}", hash.to_uppercase()),
        format!("{hash}  package/"),
        first[1..].to_owned(),
        String::new(),
    ] {
        refused(format!("{text}{bad}\n"), "malformed");
    }
    refused(format!("{text}# a note\n{first}\n"), "opens with `# Ruling");
    refused(
        format!("{text}# Ruling soon\n{first}\n"),
        "opens with `# Ruling",
    );
    let other = "0".repeat(64);
    let rewritten = text.replacen(hash, &other, 1);
    refused(rewritten, "was rewritten");

    let ruled =
        format!("{text}# Ruling 2026-12-01: a re-spin, as the header says\n{other}  {path}\n");
    let list = ordered_in_force(&ruled).unwrap();
    let before = ordered_in_force(&text).unwrap();
    assert_eq!(list.len(), before.len());
    let name = path.strip_prefix("package/").unwrap();
    assert!(
        list.contains(&(other.clone(), name.to_owned())),
        "the ruling's entry is in force"
    );
    refused(
        format!("{ruled}{other}  {path}\n"),
        "listed twice in one block",
    );
}

/// Every hex run in `text` that could name a digest, by line (ruling D3 on
/// PR #362): a run of 16 hex digits or more anywhere; a run of 7 or more
/// standing alone (no letter or digit either side); a run of more than 8
/// after `0x` (a register word has at most 8). So a commit or a run id the sheet cites by 7 hex digits or more is a digest too: name it
/// in [`NOT_AN_ELF`] or leave it out.
fn digests(text: &str) -> Vec<String> {
    let alnum = |c: Option<&u8>| c.is_some_and(u8::is_ascii_alphanumeric);
    let mut out = Vec::new();
    for (n, line) in text.lines().enumerate() {
        let b = line.as_bytes();
        let mut i = 0;
        while i < b.len() {
            if !b[i].is_ascii_hexdigit() {
                i += 1;
                continue;
            }
            let mut j = i;
            while j < b.len() && b[j].is_ascii_hexdigit() {
                j += 1;
            }
            let run = j - i;
            let prev = i.checked_sub(1).and_then(|k| b.get(k));
            let after_0x = i >= 2 && b[i - 2..i].eq_ignore_ascii_case(b"0x");
            let alone = !alnum(prev) && !alnum(b.get(j));
            if run >= 16 || (run >= 7 && alone) || (after_0x && run > 8) {
                out.push(format!("L{}: {}", n + 1, &line[i..j]));
            }
            i = j;
        }
    }
    out
}

/// Ruling D3 on PR #362: the sheet's digests are MANIFEST's ELF, exactly
/// once, and the named digests that are not an ELF's.
fn bench_names_only(text: &str, elf: &str, named: &[(&str, &str)]) -> Result<(), String> {
    let found = digests(text);
    let is = |t: &String, d: &str| t.ends_with(&format!(": {d}"));
    let elfs = found.iter().filter(|t| is(t, elf)).count();
    let other: Vec<_> = found
        .iter()
        .filter(|t| !is(t, elf) && !named.iter().any(|(d, _)| is(t, d)))
        .collect();
    if elfs != 1 || !other.is_empty() {
        return Err(format!(
            "BENCH.md must state MANIFEST.json's ELF {elf} exactly once ({elfs} found), and no other digest than the sheet's named ones (NOT_AN_ELF, S03_NOT_AN_ELF): {other:?}"
        ));
    }
    Ok(())
}

fn package_elf() -> String {
    manifest()["files"]["sentinel-01-bench.elf"]
        .as_str()
        .unwrap()
        .to_owned()
}

/// `AET-WO-4300k` (8): Sentinel-03's bench sheet is bound the same way, to
/// the ELF its package's `MANIFEST.json` names (the package is the CI
/// dispatch's, committed unchanged).
#[test]
fn sentinel_03_s_bench_sheet_names_its_package_elf() {
    let dir = root().join("fab/sentinel-03");
    let m: Value =
        serde_json::from_slice(&fs::read(dir.join("package/MANIFEST.json")).unwrap()).unwrap();
    let elf = m["files"]["sentinel-03.elf"].as_str().unwrap();
    assert_eq!(
        sha(&fs::read(dir.join("package/sentinel-03.elf")).unwrap()),
        elf
    );
    let text = fs::read_to_string(dir.join("BENCH.md")).unwrap();
    bench_names_only(&text, elf, &S03_NOT_AN_ELF).unwrap();
    for (d, _) in S03_NOT_AN_ELF {
        assert!(
            text.contains(d),
            "{d} is named but the sheet no longer cites it"
        );
    }
}

/// `AET-WO-4411`, ruled 2026-11-26T18:38Z: Sentinel-03's sheet says its rows
/// are the conditions `examples/sentinel-03.json` acknowledges for the bench.
/// A condition is acknowledged for the bench when its reason names the bench
/// (the word `bench`, any case: "a bench row", "the bench reads"). A row names
/// its conditions in backticks in its `### B-` heading.
fn rows_are_the_bench_acknowledgements(sheet: &str, spec: &Value) -> Result<(), String> {
    let rows: std::collections::BTreeSet<&str> = sheet
        .lines()
        .filter(|l| l.starts_with("### B-"))
        .flat_map(|l| l.split('`').skip(1).step_by(2))
        .collect();
    let acknowledged: std::collections::BTreeSet<&str> = spec["acknowledge_conditions"]
        .as_array()
        .ok_or("the specification has no acknowledge_conditions")?
        .iter()
        .filter(|a| {
            a["reason"]
                .as_str()
                .is_some_and(|r| r.to_ascii_lowercase().contains("bench"))
        })
        .filter_map(|a| a["id"].as_str())
        .collect();
    let missing: Vec<_> = acknowledged.difference(&rows).collect();
    let extra: Vec<_> = rows.difference(&acknowledged).collect();
    if !missing.is_empty() || !extra.is_empty() {
        return Err(format!(
            "BENCH.md's rows must be exactly the acknowledged bench rows: no row for {missing:?}; a row for no such acknowledgement {extra:?}"
        ));
    }
    Ok(())
}

fn sentinel_03_sheet_and_spec() -> (String, Value) {
    let sheet = fs::read_to_string(root().join("fab/sentinel-03/BENCH.md")).unwrap();
    let spec = serde_json::from_slice(&fs::read(root().join("examples/sentinel-03.json")).unwrap())
        .unwrap();
    (sheet, spec)
}

#[test]
fn sentinel_03_s_bench_rows_are_exactly_its_acknowledged_bench_rows() {
    let (sheet, spec) = sentinel_03_sheet_and_spec();
    rows_are_the_bench_acknowledgements(&sheet, &spec).unwrap();
}

/// The cases the check exists to fail: a row gone, a condition gone from a
/// row's heading, a row for a condition the specification does not
/// acknowledge, and an acknowledged bench condition with no row.
#[test]
fn a_bench_sheet_missing_or_adding_a_row_fails() {
    let (sheet, spec) = sentinel_03_sheet_and_spec();
    let b8 = sheet.lines().find(|l| l.starts_with("### B-8")).unwrap();
    let mut unrowed = spec.clone();
    unrowed["acknowledge_conditions"]
        .as_array_mut()
        .unwrap()
        .push(json!({"id": "planted:U99", "reason": "a bench row"}));
    for (case, text, s) in [
        ("a row gone", sheet.replace(b8, "### Gone"), &spec),
        (
            "a condition gone from a heading",
            sheet.replace(", `theta_ja_copper_mismatch:U13`", ""),
            &spec,
        ),
        (
            "a row for no acknowledgement",
            format!("{sheet}\n### B-99 Planted (`planted:U99`)\n"),
            &spec,
        ),
        ("an acknowledgement with no row", sheet.clone(), &unrowed),
    ] {
        assert!(
            rows_are_the_bench_acknowledgements(&text, s).is_err(),
            "{case}: passed"
        );
    }
}

/// `AET-WO-3308` (3): the bench sheet predicts the ELF the package carries.
#[test]
fn the_bench_sheet_names_the_package_elf() {
    let text = fs::read_to_string(root().join(BENCH)).unwrap();
    bench_names_only(&text, &package_elf(), &NOT_AN_ELF).unwrap();
}

/// The cases (3) exists to fail, and the words it must let pass, on the
/// sheet as committed.
#[test]
fn a_bench_sheet_naming_another_elf_fails() {
    let text = fs::read_to_string(root().join(BENCH)).unwrap();
    let elf = package_elf();
    let off = format!(
        "{}{}",
        &elf[..63],
        if elf.ends_with('0') { '1' } else { '0' }
    );
    let old = "008a2a59".repeat(8);
    for (case, sheet) in [
        ("one character off", text.replace(&elf, &off)),
        (
            "a prefix only",
            text.replace(&elf, &format!("{}…", &elf[..8])),
        ),
        ("the ELF twice", format!("{text}Again: {elf}.\n")),
        (
            "a second full digest in a table row",
            format!("{text}| x | `{old}` |\n"),
        ),
        (
            "the old ELF abbreviated",
            format!("{text}The ELF `008a2a59…`.\n"),
        ),
        (
            "the old ELF with three dots",
            format!("{text}The ELF 008a2a59....\n"),
        ),
        (
            "the old ELF bare, eight digits",
            format!("{text}The ELF `008a2a59`.\n"),
        ),
        (
            "the old ELF bare, seven digits",
            format!("{text}The ELF 008a2a5.\n"),
        ),
        (
            "the old ELF after 0x, nine digits",
            format!("{text}0x008a2a594\n"),
        ),
        ("the old ELF glued to a word", format!("{text}{old}s\n")),
        (
            "the ELF in capitals",
            text.replace(&elf, &elf.to_uppercase()),
        ),
    ] {
        assert!(
            bench_names_only(&sheet, &elf, &NOT_AN_ELF).is_err(),
            "{case} passed"
        );
    }
    for (case, words) in [
        (
            "register words",
            "`0x2100B007`, `0x0000_A000`, `0x22020001`",
        ),
        ("a word with seven hex letters, then a letter", "FEEDBACK"),
        ("eight hex letters after a letter", "`Xcafebabe`"),
    ] {
        assert!(
            bench_names_only(&format!("{text}{words}\n"), &elf, &NOT_AN_ELF).is_ok(),
            "{case} failed"
        );
    }
    for (d, _) in NOT_AN_ELF {
        assert!(
            text.contains(d),
            "{d} is named but the sheet no longer cites it"
        );
    }
}
